$ErrorActionPreference = "Stop"
$path = "D:\\optiflow\\src\\pages\\CadastrosPage.tsx"
$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = "$path.bak_$stamp"
Copy-Item $path $backup
Write-Host "Backup criado em $backup"

$bytes = [System.IO.File]::ReadAllBytes($path)
$hasBom = ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF)
$rawContent = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)

$hadCRLF = $rawContent.Contains("`r`n")
$content = $rawContent -replace "`r`n", "`n"

# --- Bloco 1 ---
$old1 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
$new1 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
if ($content.IndexOf($old1) -lt 0) { throw "Bloco 1 nao encontrado no arquivo - patch abortado, nada foi alterado." }
$content = $content.Replace($old1, $new1)

# --- Bloco 2 ---
$old2 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String('ZnVuY3Rpb24gZW1wdHlQcm9mRm9ybSgpIHsKICByZXR1cm4gewogICAgbmFtZTonJywgY3JvOicnLCBzcGVjaWFsdHk6J09wdG9tZXRyaWEnLCBwaG9uZTonJywgZW1haWw6JycsCiAgICBjb25zZWxob19udW1lcm86JycsIGNvbnNlbGhvX3VmOicnLCBmb3RvX3VybDonJywgYXNzaW5hdHVyYV91cmw6JycsCiAgICBsb2dpbl9lbWFpbDonJywgbG9naW5fc2VuaGE6JycsCiAgfTsKfQ=='))
$new2 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
if ($content.IndexOf($old2) -lt 0) { throw "Bloco 2 nao encontrado no arquivo - patch abortado, nada foi alterado." }
$content = $content.Replace($old2, $new2)

# --- Bloco 3 ---
$old3 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
$new3 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
if ($content.IndexOf($old3) -lt 0) { throw "Bloco 3 nao encontrado no arquivo - patch abortado, nada foi alterado." }
$content = $content.Replace($old3, $new3)

# --- Bloco 4 ---
$old4 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
$new4 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
if ($content.IndexOf($old4) -lt 0) { throw "Bloco 4 nao encontrado no arquivo - patch abortado, nada foi alterado." }
$content = $content.Replace($old4, $new4)

# --- Bloco 5 ---
$old5 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
$new5 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
if ($content.IndexOf($old5) -lt 0) { throw "Bloco 5 nao encontrado no arquivo - patch abortado, nada foi alterado." }
$content = $content.Replace($old5, $new5)

if ($hadCRLF) { $content = $content -replace "`n", "`r`n" }

if ($hasBom) {
  $utf8Bom = New-Object System.Text.UTF8Encoding($true)
  [System.IO.File]::WriteAllText($path, $content, $utf8Bom)
} else {
  $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($path, $content, $utf8NoBom)
}

Write-Host "CadastrosPage.tsx atualizado: forma de pagamento do profissional (fixo/comissao) agora e configuravel no cadastro."
Write-Host "Rode: npm run build"